// ============================================================
// Merge: ClusterInfo
// ============================================================
// MergeClusterInfo fills zero-valued fields in dst from src.
func MergeClusterInfo(dst, src *ClusterInfo) {
	if dst.OrgId == "" {
		dst.OrgId = src.OrgId
	}
	if dst.Region == "" {
		dst.Region = src.Region
	}
	if dst.Zone == "" {
		dst.Zone = src.Zone
	}
	if dst.ClusterName == "" {
		dst.ClusterName = src.ClusterName
	}
	if len(dst.Members) == 0 {
		dst.Members = src.Members
	}
}

// ============================================================
// Merge: ClusterState
// ============================================================
// MergeClusterState fills zero-valued fields in dst from src.
func MergeClusterState(dst, src *ClusterState) {
	if len(dst.Clusters) == 0 {
		dst.Clusters = src.Clusters
	}
}

// ============================================================
// Merge: PingResponse
// ============================================================
// MergePingResponse fills zero-valued fields in dst from src.
func MergePingResponse(dst, src *PingResponse) {
	if dst.Status == 0 {
		dst.Status = src.Status
	}
}

// ============================================================
// Merge: ServiceConfigState
// ============================================================
// MergeServiceConfigState fills zero-valued fields in dst from src.
func MergeServiceConfigState(dst, src *ServiceConfigState) {
	if dst.Config == nil {
		dst.Config = src.Config
	} else if src.Config != nil {
		MergeConfig(dst.Config, src.Config)
	}
}
